INSERT INTO public.scraper_sources (id, source_name, society, base_url, default_event_type, pagination_type, pagination_template, max_pages_hint, detail_is_multipage, active, extraction_instructions) VALUES
  (159, 'EANS Community Calendar', 'EANS', 'https://www.eans.org/events/event_list.asp', 'mixed', 'page_query', 'https://www.eans.org/events/event_list.asp?DGPCrSrt=&DGPCrPg={n}', 3, FALSE, TRUE, 'YourMembership community calendar (family module community_calendar.py). Listing /events/event_list.asp?DGPCrSrt=&DGPCrPg=N (15 rows a page; walk until a page adds no new id). Row: span#EventList<id> link, dd/mm/yyyy [» dd/mm/yyyy], optional Location. Detail EventDetails.aspx?id=: #SpTitleBar, bold date line, When/Where rows, free-text body with an external Info/Registration link (organiser_url). Rows already running are skipped; the EANS Annual Congress is added from /page/EANS_Congress ''Future Congresses''.'),
  (160, 'ABN Community Calendar', 'ABN', 'https://www.theabn.org/events/event_list.asp', 'mixed', 'page_query', 'https://www.theabn.org/events/event_list.asp?DGPCrSrt=&DGPCrPg={n}', 1, FALSE, TRUE, 'YourMembership community calendar (family module community_calendar.py), same markup as eans.org. Listing /events/event_list.asp (3 ABN events: Student Day, Annual Meetings 2027/2028). Detail EventDetails.aspx?id=: title, dates, When/Where, body. The Annual Meeting page has no body: its /page/annualmeeting2027 microsite page (nav link restating the title) is set as organiser_url for discovery. Third-party ''Non ABN Events'' page is not scraped.'),
  (161, 'WFNS Events', 'WFNS', 'https://wfns.org/events', 'mixed', 'single_page', NULL, 1, FALSE, TRUE, 'ASP.NET list, one long page (1.5 MB incl. archive). Only the #tab1 ''Future Events'' tab is read: table per event with day/month badge, link /events/<cat>/<id>/<slug>, bold date line, optional organiser website. Detail: h1 lblTitle, blue line ''(dd/mm/yyyy - dd/mm/yyyy) / Venue, City, , Country'', website link, announcement PDFs, body text. No fees published; organiser website becomes organiser_url.'),
  (163, 'ESE Events & Key Dates', 'ESE', 'https://www.ese-hormones.org/education-and-training/events-key-dates/', 'mixed', 'single_page', NULL, 1, FALSE, TRUE, 'Umbraco + Vue list. Cards come from POST /umbraco/api/searchapi/search (called from inside the loaded listing page; filters [], pageNumber, resultsPerPage 50, rootNodeIds [8010]); result = Name, Url, Location, EventStartDate/EventEndDate{Day,Month,Year}, TagGroupContentType. Patient forums / awareness days / deadlines dropped. Detail: hero span, intro, optional two-header-row fee grid (parse_fee_grid), REGISTER link to registrar (organiser_url), Website link for external events.'),
  (164, 'FACE – The Aesthetic Show UK', 'FACE', 'https://www.faceconference.com/', 'conference', 'single_page', NULL, 1, FALSE, TRUE, 'faceconference.com is The Aesthetic Show UK (Informa, AMWC series), one annual conference + exhibition. Next.js site behind Cloudflare: plain HTTP gets 403, the Playwright fallback reads it. Home page carries JSON-LD Event. Between editions the family sets verified_empty.')
